// Measured model figures shown on the site.
//
// Source: ./modelEvaluation.json, generated by
//   backend/scripts/evaluate_model.py --json-out ../frontend/src/data/modelEvaluation.json
// Re-run that script after changing the model; never edit
// the numbers by hand.
import evaluation from './modelEvaluation.json';

// The "pending" view is what the scanner can know before a transaction is mined.
const view = evaluation.views.pending;
const atThreshold = view.metrics.find((m) => m.threshold === evaluation.threshold);

export const pct = (value, digits = 1) => `${(value * 100).toFixed(digits)}%`;

export const modelMetrics = {
  threshold: evaluation.threshold,
  precision: atThreshold.precision,
  recall: atThreshold.recall,
  fpr: atThreshold.fpr,
  accuracy: view.accuracy,
  latencyMedianMs: view.latency_ms.median,
  latencyP95Ms: view.latency_ms.p95,
  features: evaluation.features,
  sampleSize: evaluation.sample.fraud + evaluation.sample.legit,
  sample: evaluation.sample,
  datasetRows: evaluation.dataset_rows,
  generatedAt: evaluation.generated_at,
  thresholdCurve: view.metrics,
  scoreHistogram: view.score_histogram,
  outcomes: view.outcomes,
};

/** One-line provenance note for figures derived from the evaluation. */
export const evaluationSource =
  `Measured on ${modelMetrics.sampleSize.toLocaleString()} labelled transactions from held-out addresses ` +
  `(${modelMetrics.sample.fraud.toLocaleString()} fraud / ${modelMetrics.sample.legit.toLocaleString()} legitimate), ` +
  `scored as pending transactions · ${modelMetrics.generatedAt}`;
